 static int checks,failures;static void Check(bool ok,string name){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var c in Tree(VisualTreeHelper.GetChild(o,i)))yield return c;}static T Named<T>(DependencyObject o,string n)where T:DependencyObject{return Tree(o).OfType<T>().FirstOrDefault(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(120)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}static void Click(Window w,string text){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==text).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
