 var ramp=UsageRamp.Preset("侦探蓝");Check(ramp.At(0)==TaskbarAppearance.ParseColor("#3B82F6")&&ramp.At(100)==TaskbarAppearance.ParseColor("#F78742"),"low blue high orange endpoints");var copy=ramp.Copy();copy.Stops[0].Color="#FFFFFF";Check(ramp.Stops[0].Color!="#FFFFFF","preset copies independent");var two=new UsageRamp{Stops=new List<UsageStop>{new UsageStop{Position=0,Color="#000000"},new UsageStop{Position=100,Color="#FFFFFF"}}};Check(two.At(50).R==128,"intermediate colors interpolate");bool rejected=false;two.Stops.Add(new UsageStop{Position=100,Color="#FF0000"});try{two.Validate();}catch(ArgumentException){rejected=true;}Check(rejected,"duplicate color positions rejected");
