 var folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"title-fixture");Directory.CreateDirectory(folder);var id=Guid.NewGuid().ToString();File.WriteAllText(Path.Combine(folder,"session_index.jsonl"),"bad line\n"+new JavaScriptSerializer().Serialize(new{id=id,thread_name="优化任务栏与侦探备忘录",updated_at="2026-10-23"}));var titles=new CodexSessionTitles();Check(titles.Resolve(id,null,folder)=="优化任务栏与侦探备忘录","title resolves from local metadata index");Check(titles.Resolve(id,"显式标题\n",folder)=="显式标题","explicit title has priority and strips control characters");Check(titles.Resolve("missing",null,folder)=="","missing metadata yields empty title");var feed=new CodexFeed();feed.Apply(id,"working",DateTime.UtcNow,"已知标题");feed.Apply(id,"ended",DateTime.UtcNow.AddSeconds(1));Check(feed.Tasks[id].Title=="已知标题","later events preserve existing title");
