 Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.Width=1100;w.Height=800;w.ShowPage("任务栏外观");Click(w,"配色与文字");Named<ComboBox>(w,"配色对象").SelectedIndex=2;Pump();Named<ComboBox>(w,"配色预设").SelectedItem="NVIDIA 绿";Pump();var bar=Named<UsageRampBar>(w,"可编辑配色条");bar.SelectPoint(35);Pump();Check(bar.Ramp.Stops.Count==5,"click color bar adds intermediate stop");Named<TextBox>(w,"配色颜色点颜色").Text="#12AB34";Pump();Check(bar.Ramp.Stops.Any(s=>s.Position==35&&s.Color=="#12AB34"),"new color point is editable");Named<ComboBox>(w,"配色过渡方式").SelectedIndex=1;Named<Slider>(w,"配色色块数量").Value=24;Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.Items.All(i=>i.UsageRamp!=null&&i.UsageRamp.Mode=="mosaic"&&i.UsageRamp.Cells==24&&i.UsageRamp.Stops.Count==5),"all items accept same custom themed ramp");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(restored.Config.Monitor.Appearance.Item("gpu").UsageRamp.Stops.Any(s=>s.Color=="#12AB34"),"custom stop survives actual runtime reload");restored.Telemetry.Dispose();Shot(w,Path.Combine(args[0],"usage-ramp-editor.png"));w.SetTheme("b",false);Pump();Shot(w,Path.Combine(args[0],"usage-ramp-editor-b.png"));
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"ramp-title-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,live_codex_metadata_read=false}));return failures==0?0:1;}
